# Enumerate simple loops through the battery with both switches closed
edges={'bulb1':('P','B'),'bulb2':('B','C'),'S':('B','C'),'wireCN':('C','N'),'bulb3':('P','D'),'T':('D','N')}
def paths(start,end,used,node):
    if node==end:
        yield list(used); return
    for name,(a,b) in edges.items():
        if name in used: continue
        if node in (a,b):
            nxt=b if node==a else a
            visited=set()
            for u in used:
                visited.update(edges[u])
            if nxt in visited and not nxt==end: continue
            yield from paths(start,end,used+[name],nxt)
loops=[frozenset(p) for p in paths('P','N',[],'P')]
named={frozenset(l)-{'wireCN'} for l in loops}
assert named=={frozenset({'bulb1','S'}),frozenset({'bulb3','T'}),frozenset({'bulb1','bulb2'})}
assert len(named)==3
print('ALL_CHECKS_PASSED')
